// ─── Collect all rows ────────────────────────────────────────────────────────
const rows = $input.all().map(i => i.json);

const criticalErrors = [];
const warnings       = [];

// ─── No data check ───────────────────────────────────────────────────────────
if (!rows || rows.length === 0) {
  return [{ json: {
    passed: false,
    guardrail_type: null,
    critical_errors: ['Excel file appears empty — no data rows found.'],
    warnings: [],
    stats: { total_rows: 0, missing_cells: 0, invalid_dates: 0, invalid_statuses: 0 }
  }}];
}

// ════════════════════════════════════════════════════════════════════════════
// GUARDRAIL 1 — DOMAIN CHECK
// Only Credit Card Processing domain projects are accepted
// ════════════════════════════════════════════════════════════════════════════
const CARD_DOMAIN_KEYWORDS = [
  'credit card','debit card','payment card','card launch','card program','card issuance',
  'card production','card network','card scheme','card processing','card holder','cardholder',
  'bin','bin procurement','bin range','pan','cvv','cvc','card number',
  'issuer','issuing bank','issuing','acquiring','acquirer','card issuer',
  'visa','mastercard','master card','amex','american express','discover','unionpay','rupay','jcb',
  'chargeback','dispute','fraud detection','fraud scoring','fraud prevention',
  'authorization','authorisation','auth request','clearing','settlement','reconciliation',
  'payment processing','payment gateway','payment network',
  'pos terminal','point of sale','atm','contactless','emv','chip and pin',
  'reward points','loyalty points','interchange','interchange fee',
  'tokenization','tokenisation','3d secure','3ds','secure payment',
  'card not present','cnp','card present',
  'credit limit','debit limit','spending limit','card activation'
];

const allText = rows.flatMap(row =>
  Object.values(row).map(v => String(v || '').toLowerCase())
).join(' ');

const domainMatch = CARD_DOMAIN_KEYWORDS.some(kw => allText.includes(kw));

if (!domainMatch) {
  return [{ json: {
    passed: false,
    guardrail_type: 'domain',
    critical_errors: [
      'DOMAIN GUARDRAIL: This project does not appear to belong to the Credit Card Processing domain. ' +
      'This tracker only accepts projects related to card issuance, acquiring, fraud, disputes, payments, BIN management, or card network operations. ' +
      'Please verify your project content or speak to your administrator.'
    ],
    warnings: [],
    stats: { total_rows: rows.length }
  }}];
}

// ════════════════════════════════════════════════════════════════════════════
// GUARDRAIL 2 — CONTENT CHECK
// Offensive language, hate speech, threats, explicit content
// ════════════════════════════════════════════════════════════════════════════
const BAD_WORDS = [
  // Profanity
  'fuck','fucking','fucked','fucker','shit','shitty','bullshit','horseshit',
  'ass','asshole','arsehole','bitch','bastard','crap','piss','prick','dick',
  'cock','cunt','wanker','twat','tosser',
  // Hate speech & slurs (racial/ethnic)
  'nigger','nigga','faggot','fag','dyke','tranny','spic','kike','chink',
  'wetback','raghead','towelhead','cracker','gook','nip','wop','honky',
  'beaner','coon','jigaboo','jungle bunny','sandnigger','zipperhead',
  // Hate speech (religious/gender)
  'nazi','heil','white supremacist','kkk','jihadi',
  // Threats & violence
  'kill you','murder','rape','terrorist','bomb','shoot','die bitch',
  'suicide','self-harm','self harm','i will kill',
  // Explicit
  'porn','pornography','xxx','nude','naked'
];

const allCells = rows.flatMap(row =>
  Object.values(row).map(v => String(v || '').toLowerCase())
);

const badWordsFound = [];
for (const cell of allCells) {
  for (const word of BAD_WORDS) {
    const regex = new RegExp('\\b' + word.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\b', 'i');
    if (regex.test(cell) && !badWordsFound.includes(word)) {
      badWordsFound.push(word);
    }
  }
}

if (badWordsFound.length > 0) {
  return [{ json: {
    passed: false,
    guardrail_type: 'content',
    critical_errors: [
      `CONTENT GUARDRAIL: Inappropriate or offensive content was detected in your spreadsheet (${badWordsFound.length} flagged term(s) found). ` +
      'All content must be professional and workplace-appropriate. ' +
      'Please review every cell, remove offensive language, and re-upload.'
    ],
    warnings: [],
    stats: { total_rows: rows.length, flagged_terms: badWordsFound.length }
  }}];
}

// ════════════════════════════════════════════════════════════════════════════
// STRUCTURAL VALIDATION
// Column presence, data integrity, formats
// ════════════════════════════════════════════════════════════════════════════
const REQUIRED_COLS = [
  { key: 'step',        patterns: ['step number','step no','step#','step num','#'] },
  { key: 'description', patterns: ['step description','description','task','activity'] },
  { key: 'dri_name',    patterns: ['dri name','responsible party','dri','owner','assignee'] },
  { key: 'dri_email',   patterns: ['dri email','email','dri email address','email address'] },
  { key: 'est_start',   patterns: ['estimated start','est start','start date','est start date'] },
  { key: 'est_end',     patterns: ['estimated end','est end','end date','est end date','due date'] },
  { key: 'status',      patterns: ['status'] }
];

const OPTIONAL_COLS = [
  { key: 'actual',     patterns: ['actual completion','actual date','completed date'] },
  { key: 'depends_on', patterns: ['depends on','dependency','depends','prerequisites'] },
  { key: 'security',   patterns: ['security flag','security','secure'] },
  { key: 'notes',      patterns: ['notes','comments','remarks'] }
];

const VALID_STATUSES = ['to do','in progress','done','blocked','todo','complete','completed','not started'];

const colMap = {};
for (const col of REQUIRED_COLS) {
  const found = Object.keys(rows[0]).find(h =>
    col.patterns.some(p => h.toLowerCase().trim().includes(p))
  );
  if (found) {
    colMap[col.key] = found;
  } else {
    criticalErrors.push(`Required column missing: "${col.patterns[0]}" not found in headers. Found: ${Object.keys(rows[0]).join(', ')}`);
  }
}

const optMap = {};
for (const col of OPTIONAL_COLS) {
  const found = Object.keys(rows[0]).find(h =>
    col.patterns.some(p => h.toLowerCase().trim().includes(p))
  );
  if (found) optMap[col.key] = found;
}

if (rows.length < 3) {
  criticalErrors.push(`Too few rows: only ${rows.length} row(s). Minimum 3 required.`);
}

let missingCells = 0, invalidDates = 0, invalidStatuses = 0, invalidEmails = 0;
const stepNumbers = [];
const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const dateRe  = /^\d{1,2}[\/\-\.]\d{1,2}[\/\-\.]\d{2,4}$/;

rows.forEach((row, idx) => {
  const rowNum = idx + 2;

  for (const [key, col] of Object.entries(colMap)) {
    const val = (row[col] || '').toString().trim();
    if (!val) {
      missingCells++;
      if (missingCells <= 5) criticalErrors.push(`Row ${rowNum}: "${col}" is empty — required field.`);
    }
  }

  if (colMap.step) {
    const stepVal = (row[colMap.step] || '').toString().trim();
    if (stepVal && isNaN(parseInt(stepVal))) {
      warnings.push(`Row ${rowNum}: Step number "${stepVal}" is not numeric.`);
    } else if (stepVal) {
      stepNumbers.push(parseInt(stepVal));
    }
  }

  for (const dateCol of ['est_start','est_end']) {
    if (colMap[dateCol]) {
      const dateVal = (row[colMap[dateCol]] || '').toString().trim();
      if (dateVal && !dateRe.test(dateVal) && isNaN(Date.parse(dateVal))) {
        invalidDates++;
        if (invalidDates <= 3) criticalErrors.push(`Row ${rowNum}: Invalid date "${dateVal}" in "${colMap[dateCol]}". Use DD/MM/YYYY.`);
      }
    }
  }

  if (colMap.status) {
    const statusVal = (row[colMap.status] || '').toString().trim().toLowerCase();
    if (statusVal && !VALID_STATUSES.includes(statusVal)) {
      invalidStatuses++;
      if (invalidStatuses <= 3) criticalErrors.push(`Row ${rowNum}: Invalid status "${row[colMap.status]}". Must be: To Do, In Progress, Done, Blocked.`);
    }
  }

  if (colMap.dri_email) {
    const emailVal = (row[colMap.dri_email] || '').toString().trim();
    if (emailVal && !emailRe.test(emailVal)) {
      invalidEmails++;
      if (invalidEmails <= 3) warnings.push(`Row ${rowNum}: Invalid email "${emailVal}".`);
    }
  }

  if (optMap.security) {
    const secVal = (row[optMap.security] || '').toString().trim().toUpperCase();
    if (secVal && secVal !== 'Y' && secVal !== 'N') {
      warnings.push(`Row ${rowNum}: Security flag "${row[optMap.security]}" must be Y or N.`);
    }
  }

  if (optMap.depends_on) {
    const depVal = (row[optMap.depends_on] || '').toString().trim();
    if (depVal) {
      const depNums = depVal.split(',').map(d => parseInt(d.trim())).filter(d => !isNaN(d));
      depNums.forEach(d => {
        if (d >= parseInt((row[colMap.step] || '0'))) {
          warnings.push(`Row ${rowNum}: Dependency step ${d} is circular or forward — check step order.`);
        }
      });
    }
  }
});

if (stepNumbers.length > 1) {
  const sorted = [...stepNumbers].sort((a, b) => a - b);
  for (let i = 1; i < sorted.length; i++) {
    if (sorted[i] - sorted[i-1] > 1) {
      warnings.push(`Step sequence gap: step ${sorted[i-1]} jumps to ${sorted[i]}.`);
    }
  }
}

if (missingCells  > 5)  criticalErrors.push(`... and ${missingCells - 5} more missing required cells.`);
if (invalidDates  > 3)  criticalErrors.push(`... and ${invalidDates - 3} more invalid dates.`);
if (invalidStatuses > 3) criticalErrors.push(`... and ${invalidStatuses - 3} more invalid statuses.`);
if (invalidEmails > 3)  warnings.push(`... and ${invalidEmails - 3} more invalid emails.`);

const passed = criticalErrors.length === 0;

return [{ json: {
  passed,
  guardrail_type: null,
  critical_errors: criticalErrors,
  warnings,
  stats: {
    total_rows:          rows.length,
    missing_cells:       missingCells,
    invalid_dates:       invalidDates,
    invalid_statuses:    invalidStatuses,
    invalid_emails:      invalidEmails,
    optional_cols_found: Object.keys(optMap),
    headers_detected:    Object.keys(rows[0])
  }
}}];

const v = $input.first().json;
const warnings = v.warnings || [];
const stats = v.stats || {};

const summary = [
  `✅ Validation passed — your Excel file is ready to process.`,
  ``,
  `📊 Summary:`,
  `   • ${stats.total_rows} data rows detected`,
  `   • ${stats.headers_detected ? stats.headers_detected.length : '?'} columns found`,
  stats.optional_cols_found && stats.optional_cols_found.length > 0
    ? `   • Optional columns detected: ${stats.optional_cols_found.join(', ')}`
    : `   • No optional columns (Dependencies, Security Flag, Notes) — that is fine`,
  ``,
  warnings.length > 0
    ? `⚠️ Warnings (non-blocking):\n${warnings.map(w => `   • ${w}`).join('\n')}`
    : `✅ No warnings.`,
  ``,
  `▶ Proceeding to generate your project tracker...`
].join('\n');

return [{ json: {
  status: 'success',
  reply: summary,
  passed: true,
  warnings: v.warnings,
  stats: v.stats
}}];

const v = $input.first().json;
const errors       = v.critical_errors || [];
const warnings     = v.warnings || [];
const stats        = v.stats || {};
const guardrailType = v.guardrail_type;

let prompt;

if (guardrailType === 'domain') {
  prompt = `A user tried to upload an Excel project file to the Credit Card Processing Multi-Project Tracker but it was rejected because the project content does not match the Credit Card Processing domain.

REJECTION REASON:
${errors[0]}

Write a polite, professional message explaining:
1. That this tool is purpose-built for credit card processing, issuing, acquiring, fraud, disputes, and payment operations projects
2. The type of projects that ARE accepted (give 3-4 examples: BIN Procurement, Fraud Detection, Chargeback Management, Card Network Migration)
3. That they should speak to their administrator if they believe this is a mistake

Keep under 150 words. Be respectful — do not make the user feel they did something wrong.`;
} else if (guardrailType === 'content') {
  prompt = `A user tried to upload an Excel project file to the Multi-Project Tracker but it was rejected because the file contained inappropriate or offensive content.

REJECTION REASON:
${errors[0]}

Write a firm but professional message explaining:
1. That all uploaded content must meet workplace and professional standards
2. That the file contained language that does not meet those standards (do NOT reveal which words were found)
3. That they should review and clean all cells in the spreadsheet and re-upload
4. That repeated violations may be escalated to their manager

Keep under 120 words. Be firm but not accusatory.`;
} else {
  const errorList = errors.map((e, i) => `${i+1}. ${e}`).join('\n');
  const warnList  = warnings.length > 0 ? warnings.map((w, i) => `${i+1}. ${w}`).join('\n') : 'None';

  prompt = `An Excel file was uploaded to the Multi-Project Tracker and failed structural validation.

CRITICAL ERRORS (must fix):
${errorList}

WARNINGS (recommended):
${warnList}

FILE STATS:
- Total rows: ${stats.total_rows}
- Missing required cells: ${stats.missing_cells}
- Invalid dates: ${stats.invalid_dates}
- Invalid status values: ${stats.invalid_statuses}

Write a clear, friendly message telling the user exactly what to fix and how. Use bullet points. Reference row numbers and column names. End with encouragement to re-upload. Keep under 250 words.`;
}

return [{ json: {
  prompt,
  passed: false,
  guardrail_type: guardrailType,
  critical_errors: errors,
  warnings,
  stats
}}];

const item = $input.first().json;
return [{ json: {
  status:   'success',
  passed:   true,
  reply:    item.reply,
  warnings: item.warnings || [],
  stats:    item.stats || {},
  next_step: 'proceed_to_generation',
  timestamp: new Date().toISOString()
}}];

const apiResp = $input.first().json;
const valData = $('Build Error Context').first().json;

const friendlyMsg =
  apiResp.content && apiResp.content[0] && apiResp.content[0].text
    ? apiResp.content[0].text
    : `❌ Validation failed with ${valData.critical_errors.length} critical error(s).\n\n` +
      valData.critical_errors.map(e => `• ${e}`).join('\n') +
      (valData.warnings.length > 0 ? '\n\nWarnings:\n' + valData.warnings.map(w => `• ${w}`).join('\n') : '');

return [{ json: {
  status:          'error',
  passed:          false,
  reply:           friendlyMsg,
  critical_errors: valData.critical_errors,
  warnings:        valData.warnings,
  stats:           valData.stats,
  next_step:       'fix_and_reupload',
  timestamp:       new Date().toISOString()
}}];
